import React from "react";
import { useForm, Controller, SubmitHandler } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import {
  TextField,
  Button,
  FormControl,
  FormLabel,
  FormControlLabel,
  RadioGroup,
  Radio,
  Checkbox,
  FormGroup,
  Box,
  Typography,
} from "@mui/material";
import { useTranslation } from "react-i18next";
import { db } from "../../firebaseConfig"; // Ajusta la ruta según tu estructura
import { collection, addDoc, Timestamp } from "firebase/firestore";
import emailjs from "@emailjs/browser";

const phoneRegExp = /^\(\d{3}\) \d{3} \d{4}$/;

const schema: yup.ObjectSchema<FormData> = yup.object({
  fullName: yup.string().required("Full name is required"),
  email: yup.string().email("Invalid email").required("Email is required"),
  phone: yup
    .string()
    .matches(phoneRegExp, "Phone must be in format (XXX) XXX XXXX")
    .required("Phone is required"),
  contactBy: yup.string().required("Contact preference is required"),
  interests: yup.array().of(yup.string().required()).min(1, "Select at least one interest").required(),
}) as yup.ObjectSchema<FormData>;

type FormData = {
  fullName: string;
  email: string;
  phone: string;
  contactBy: string;
  interests: string[];
};

export default function ContactForm() {
  const {
    control,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm<FormData>({
    resolver: yupResolver(schema),
    defaultValues: {
      fullName: '',
      email: '',
      phone: '',
      contactBy: '',
      interests: [],
    },
  });

  const { t } = useTranslation();

  console.log("serviceId:", process.env.GATSBY_EMAILJS_SERVICE_ID);
  console.log("templateId:", process.env.GATSBY_EMAILJS_TEMPLATE_ID);
  console.log("publicKey:", process.env.GATSBY_EMAILJS_PUBLIC_KEY);

  const onSubmit: SubmitHandler<FormData> = async (data) => {
    try {
      // 1. Save to Firestore
      const docRef = await addDoc(collection(db, "contactMessages"), {
        ...data,
        createdAt: Timestamp.now(),
      });

      console.log("Document written with ID: ", docRef.id);


      // 2. Send email via EmailJS
      const serviceId = process.env.GATSBY_EMAILJS_SERVICE_ID;
      const templateId = process.env.GATSBY_EMAILJS_TEMPLATE_ID;
      const publicKey = process.env.GATSBY_EMAILJS_PUBLIC_KEY;

      if (!serviceId || !templateId || !publicKey) {
        console.error("Missing EmailJS environment variables");
        return;
      }

      await emailjs.send(serviceId, templateId, {
        fullName: data.fullName,
        email: data.email,
        phone: data.phone,
        contactBy: data.contactBy,
        interests: data.interests.join(", "),
      }, publicKey);


      console.log("Email sent!");
      reset();
    } catch (error) {
      console.error("Error submitting form:", error);
    }
  };

  return (
    <Box component="form" onSubmit={handleSubmit(onSubmit)} sx={{ maxWidth: 600, mx: "auto", p: 3, bgcolor: "white", boxShadow: 3, borderRadius: 2 }}>
      <Typography variant="h5" mb={2}>Contact Form</Typography>

      <Controller
        name="fullName"
        control={control}
        render={({ field }) => (
          <TextField {...field} label="Full Name" fullWidth margin="normal" error={!!errors.fullName} helperText={errors.fullName?.message} />
        )}
      />

      <Controller
        name="email"
        control={control}
        render={({ field }) => (
          <TextField {...field} label="Email" type="email" fullWidth margin="normal" error={!!errors.email} helperText={errors.email?.message} />
        )}
      />

 <Controller
  name="phone"
  control={control}
  rules={{
    validate: (value) => {
      const digitsOnly = value.replace(/\D/g, "");
      return digitsOnly.length === 10 || t("form.errors.phone") || "Invalid phone number";
    },
  }}
  render={({ field: { onChange, value, ...field } }) => (
    <TextField
      {...field}
      value={value}
      onChange={(e) => {
        const digits = e.target.value.replace(/\D/g, "").slice(0, 10);
        const formatted = digits.replace(
          /(\d{0,3})(\d{0,3})(\d{0,4})/,
          (_, p1, p2, p3) =>
            `${p1 ? `(${p1}` : ""}${p2 ? `) ${p2}` : ""}${p3 ? ` ${p3}` : ""}`
        );
        onChange(formatted);
      }}
      label="Phone"
      placeholder="(123) 456 7890"
      fullWidth
      margin="normal"
      error={!!errors.phone}
      helperText={errors.phone?.message}
    />
  )}
/>









      <FormControl component="fieldset" margin="normal">
        <FormLabel component="legend">Do you want to be contacted by?</FormLabel>
        <Controller
          name="contactBy"
          control={control}
          render={({ field }) => (
            <RadioGroup row {...field}>
              <FormControlLabel value="email" control={<Radio />} label="Email" />
              <FormControlLabel value="phone" control={<Radio />} label="Phone" />
              <FormControlLabel value="whatsapp" control={<Radio />} label="WhatsApp" />
            </RadioGroup>
          )}
        />
        <Typography variant="caption" color="error">{errors.contactBy?.message}</Typography>
      </FormControl>

      <FormControl component="fieldset" margin="normal">
        <FormLabel component="legend">Are you interested in?</FormLabel>
        <FormGroup>
          {["product-1", "product-2", "product-3"].map((product) => (
            <FormControlLabel
              key={product}
              control={
                <Controller
                  name="interests"
                  control={control}
                  render={({ field }) => (
                    <Checkbox
                      checked={(field.value ?? []).includes(product)}
                      onChange={(e) => {
                        const checked = e.target.checked;
                        const value = field.value;
                        if (checked) {
                          field.onChange([...(value ?? []), product]);
                        } else {
                          field.onChange((value ?? []).filter((v) => v !== product));
                        }
                      }}
                    />
                  )}
                />
              }
              label={product.replace("-", " ").replace(/\b\w/g, (l) => l.toUpperCase())}
            />
          ))}
        </FormGroup>
        <Typography variant="caption" color="error">{errors.interests?.message}</Typography>
      </FormControl>

      <Button type="submit" variant="contained" color="primary" sx={{ mt: 2 }}>
        Send
      </Button>
    </Box>
  );
}
